package com.tigeriq.v44;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.view.Display;
import android.view.View;
import com.tigeriq.camera.FloatingCarRearIcon;
import com.tigeriq.camera.RemoteShortcutTouchHelper;
import com.ultracar.dexsplit.ui.TigerIQBridge;

public final class CameraQuickButton extends View {
    private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

    public CameraQuickButton(Context context) {
        super(context);
        setContentDescription("Camera lùi");
        setClickable(true);
        setFocusable(true);
        setOnClickListener(new OnClickListener() {
            @Override
            public void onClick(View v) {
                try {
                    TigerIQBridge.toggleCamera();
                } catch (Throwable ignored) {
                }
                invalidate();
            }
        });
        setOnLongClickListener(new OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                try {
                    Display d = getDisplay();
                    int displayId = d != null ? d.getDisplayId() : 0;
                    RemoteShortcutTouchHelper.launchConfigUi(getContext(), displayId);
                } catch (Throwable ignored) {
                }
                return true;
            }
        });
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);
        int w = getWidth();
        int h = getHeight();
        if (w <= 0 || h <= 0) {
            return;
        }
        try {
            FloatingCarRearIcon.draw(canvas, this.paint, w, h, TigerIQBridge.sCameraEnabled);
        } catch (Throwable ignored) {
        }
    }
}

package com.tigeriq.v44;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;
import android.os.Handler;
import android.os.Looper;
import android.os.SystemClock;
import android.view.MotionEvent;
import android.view.View;
import android.widget.Toast;
import com.tigeriq.camera.DexShotRemoteHelper;

public final class DexShotQuickButton extends View {
    private static final int PHASE_READY = 0;
    private static final int PHASE_COUNTDOWN = 1;
    private static final int PHASE_UPLOADING = 2;
    private static final int PHASE_PROCESSING = 3;
    private static final int PHASE_COMPLETE = 4;
    private static final int PHASE_ERROR = 5;

    private static volatile int phase = PHASE_READY;
    private static volatile long deadlineAt = 0L;
    private static volatile String statusMsg = "";
    private static int generation = 0;
    private static final Handler MAIN = new Handler(Looper.getMainLooper());

    private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final float density;
    private long downAt = 0L;
    private boolean longTriggered = false;

    private final Runnable animTick = new Runnable() {
        @Override
        public void run() {
            if (isAttachedToWindow()) {
                invalidate();
                if (phase != PHASE_READY) {
                    postDelayed(this, 70L);
                }
            }
        }
    };

    private final Runnable longPressTask = new Runnable() {
        @Override
        public void run() {
            longTriggered = true;
            String msg = statusMsg;
            if (msg == null || msg.trim().isEmpty()) {
                msg = phase == PHASE_READY
                        ? "Nút T DeX sẵn sàng. Chạm nhanh để chụp."
                        : "Ảnh DeX đang chờ upload hoặc đối chiếu.";
            }
            Toast.makeText(getContext(), msg, Toast.LENGTH_LONG).show();
        }
    };

    public DexShotQuickButton(Context context) {
        super(context);
        this.density = context.getResources().getDisplayMetrics().density;
        setContentDescription("TigerIQ Driver T · chụp ảnh DeX");
        setClickable(true);
        setFocusable(true);
        setOnTouchListener(new OnTouchListener() {
            @Override
            public boolean onTouch(View v, MotionEvent event) {
                int action = event.getAction();
                if (action == MotionEvent.ACTION_DOWN) {
                    downAt = SystemClock.uptimeMillis();
                    longTriggered = false;
                    MAIN.removeCallbacks(longPressTask);
                    MAIN.postDelayed(longPressTask, 650L);
                    return true;
                }
                if (action == MotionEvent.ACTION_UP) {
                    MAIN.removeCallbacks(longPressTask);
                    if (!longTriggered && SystemClock.uptimeMillis() - downAt < 650L) {
                        onQuickTap();
                    }
                    return true;
                }
                if (action == MotionEvent.ACTION_CANCEL) {
                    MAIN.removeCallbacks(longPressTask);
                    return false;
                }
                return false;
            }
        });
    }

    private void onQuickTap() {
        Context ctx = getContext();
        if (ctx == null) {
            return;
        }
        boolean driverInstalled = false;
        try {
            ctx.getPackageManager().getPackageInfo("app.tigeriq.drivetrack", 0);
            driverInstalled = true;
        } catch (Throwable ignored) {
        }
        if (!driverInstalled) {
            setPhase(PHASE_ERROR, "Chưa cài TigerIQ Driver", 3000L);
            Toast.makeText(ctx, "Chưa cài app TigerIQ Driver để chụp DeX.", Toast.LENGTH_SHORT).show();
            return;
        }
        try {
            DexShotRemoteHelper.triggerDexShot(ctx);
            startCaptureCycle();
        } catch (Throwable th) {
            setPhase(PHASE_ERROR, "Lỗi kích hoạt chụp T", 3000L);
        }
    }

    private void startCaptureCycle() {
        final int gen = ++generation;
        phase = PHASE_COUNTDOWN;
        deadlineAt = System.currentTimeMillis() + 12000L;
        statusMsg = "Đã gửi lệnh chụp DeX; chờ 12 giây gom cuốc.";
        kickAnim();
        MAIN.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (generation != gen) return;
                phase = PHASE_UPLOADING;
                deadlineAt = 0L;
                statusMsg = "Đang tải ảnh DeX lên xử lý...";
                kickAnim();
            }
        }, 12000L);
        MAIN.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (generation != gen) return;
                phase = PHASE_PROCESSING;
                statusMsg = "AI đang đọc ảnh DeX...";
                kickAnim();
            }
        }, 15000L);
        MAIN.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (generation != gen) return;
                phase = PHASE_COMPLETE;
                statusMsg = "Đã xử lý xong ảnh chụp DeX.";
                kickAnim();
            }
        }, 19000L);
        MAIN.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (generation != gen) return;
                phase = PHASE_READY;
                statusMsg = "";
                kickAnim();
            }
        }, 21500L);
    }

    private void setPhase(int nextPhase, String msg, long resetDelayMs) {
        final int gen = ++generation;
        phase = nextPhase;
        deadlineAt = 0L;
        statusMsg = msg;
        kickAnim();
        if (resetDelayMs > 0L) {
            MAIN.postDelayed(new Runnable() {
                @Override
                public void run() {
                    if (generation == gen) {
                        phase = PHASE_READY;
                        statusMsg = "";
                        kickAnim();
                    }
                }
            }, resetDelayMs);
        }
    }

    private void kickAnim() {
        invalidate();
        removeCallbacks(this.animTick);
        if (isAttachedToWindow()) {
            post(this.animTick);
        }
    }

    @Override
    protected void onAttachedToWindow() {
        super.onAttachedToWindow();
        removeCallbacks(this.animTick);
        post(this.animTick);
    }

    @Override
    protected void onDetachedFromWindow() {
        removeCallbacks(this.animTick);
        super.onDetachedFromWindow();
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);
        float min = Math.min(getWidth(), getHeight());
        if (min <= 0.0f) {
            return;
        }
        float cx = min * 0.5f;
        float rOuter = min * 0.43f;

        this.paint.reset();
        this.paint.setAntiAlias(true);
        this.paint.setStyle(Paint.Style.FILL);
        this.paint.setColor(0xE0101826);
        canvas.drawCircle(cx, cx, rOuter, this.paint);

        this.paint.setStyle(Paint.Style.STROKE);
        this.paint.setStrokeWidth(Math.max(2.0f, min * 0.045f));
        this.paint.setColor(phase == PHASE_ERROR ? 0xFFFF5722 : (phase == PHASE_COMPLETE ? 0xFFBAFF24 : 0xFF00E5FF));
        canvas.drawCircle(cx, cx, rOuter, this.paint);

        int curPhase = phase;
        if (curPhase == PHASE_READY) {
            this.paint.setStyle(Paint.Style.FILL);
            this.paint.setColor(0xFFFFFFFF);
            this.paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
            this.paint.setTextAlign(Paint.Align.CENTER);
            this.paint.setTextSize(min * 0.48f);
            canvas.drawText("T", cx, cx - ((this.paint.ascent() + this.paint.descent()) * 0.5f), this.paint);
            return;
        }

        float rInner = min * 0.36f;
        this.paint.setStyle(Paint.Style.FILL);
        this.paint.setColor(0xE50C121D);
        canvas.drawCircle(cx, cx, rInner, this.paint);

        float sec = SystemClock.uptimeMillis() / 1000.0f;
        if (curPhase == PHASE_UPLOADING || curPhase == PHASE_PROCESSING) {
            float pulse = ((float) Math.sin(sec * 4.5d) * 0.5f) + 0.5f;
            float r1 = rInner * 0.89f;
            RectF rect1 = new RectF(cx - r1, cx - r1, cx + r1, cx + r1);
            float r2 = rInner * 0.69f;
            RectF rect2 = new RectF(cx - r2, cx - r2, cx + r2, cx + r2);

            this.paint.setStyle(Paint.Style.STROKE);
            this.paint.setStrokeCap(Paint.Cap.ROUND);
            this.paint.setStrokeWidth(this.density * 2.0f);
            this.paint.setColor(0x3867E8F9);
            canvas.drawCircle(cx, cx, r1, this.paint);

            this.paint.setColor(0xFF4EFFF0);
            this.paint.setStrokeWidth(((0.9f * pulse) + 2.5f) * this.density);
            this.paint.setShadowLayer(((4.0f * pulse) + 3.5f) * this.density, 0.0f, 0.0f, 0xFF55FF00);
            canvas.drawArc(rect1, (170.0f * sec) % 360.0f, (pulse * 75.0f) + 100.0f, false, this.paint);

            this.paint.clearShadowLayer();
            this.paint.setColor(0xFF9300E3);
            this.paint.setStrokeWidth(this.density * 1.5f);
            canvas.drawArc(rect2, 350.0f - ((sec * 112.0f) % 360.0f), 65.0f, false, this.paint);

            this.paint.setStyle(Paint.Style.FILL);
            this.paint.setColor(0xFFB7FF2B);
            this.paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
            this.paint.setTextAlign(Paint.Align.CENTER);
            this.paint.setTextSize(min * 0.22f);
            String lbl = curPhase == PHASE_UPLOADING ? "↑" : "AI";
            canvas.drawText(lbl, cx, cx - ((this.paint.ascent() + this.paint.descent()) * 0.5f), this.paint);
            return;
        }

        this.paint.setStyle(Paint.Style.FILL);
        this.paint.setTextAlign(Paint.Align.CENTER);
        this.paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        if (curPhase == PHASE_COUNTDOWN) {
            long rem = Math.max(deadlineAt - System.currentTimeMillis(), 0L);
            int secLeft = (int) Math.ceil(rem / 1000.0d);
            this.paint.setColor(0xFFFFFFFF);
            this.paint.setTextSize(min * 0.38f);
            canvas.drawText(String.valueOf(secLeft), cx, cx - ((this.paint.ascent() + this.paint.descent()) * 0.5f), this.paint);
        } else if (curPhase == PHASE_COMPLETE) {
            this.paint.setColor(0xFFBAFF24);
            this.paint.setTextSize(min * 0.44f);
            canvas.drawText("✓", cx, cx - ((this.paint.ascent() + this.paint.descent()) * 0.5f), this.paint);
        } else if (curPhase == PHASE_ERROR) {
            this.paint.setColor(0xFFFF5722);
            this.paint.setTextSize(min * 0.36f);
            canvas.drawText("!", cx, cx - ((this.paint.ascent() + this.paint.descent()) * 0.5f), this.paint);
        }
    }
}

